// Real CometBFT qualification on the harness's disposable keys and balances.
import assert from 'node:assert/strict';import fs from 'node:fs';import {join} from 'node:path';
import {keys,hash,sign} from '../crypto.mjs';import {envelope,stateHash} from '../core.mjs';
import {CONTROL,RESOURCE_FEATURE} from '../authority.mjs';import {RESERVES,reserveConsent,unrestrictedDevelopmentControls} from '../network-reserves.mjs';
import {LIABILITY,liabilityConsent,attestationBody} from '../payment-liability.mjs';import {resourcePaymentId} from '../resource-limits.mjs';import {oid} from '../payment-model.mjs';
export async function protectionNetworkQA(e){
 const {homes,config,f,until,send,stopNode,startNode,pass,local}=e;
 const state=async(i=0)=>(await local(i,{method:'snapshot'})).value.state,wire=(a,key=f.alice)=>envelope(config,a,key);
 const validators=homes.slice(0,10).map(h=>{const k=JSON.parse(fs.readFileSync(join(h,'config/priv_validator_key.json')));return {publicKey:Buffer.from(k.pub_key.value,'base64').toString('base64url'),privateKey:Buffer.concat([Buffer.from('302e020100300506032b657004220420','hex'),Buffer.from(k.priv_key.value,'base64').subarray(0,32)]).toString('base64url')};});
 const approvals=b=>validators.slice(0,7).map(k=>({key:k.publicKey,signature:sign(b,k.privateKey)})),submit=async a=>{const r=await send(a);assert.equal(r.code,0,r.log);};
 let s=await state();const resource={domain:CONTROL+'/FEATURE',network:config.chainId,configHash:hash(config),generation:0,feature:RESOURCE_FEATURE,notBefore:s.height,expires:s.height+6,activation:s.height+8};await submit(wire({type:'ENABLE_RESOURCE_LIMITS',certificate:{body:resource,approvals:approvals(resource)}}));await until(async()=>{s=await state();return s.height>=resource.activation;});
 const founder=keys(),backups=Array.from({length:3},keys),policy={warmup:{allocation:'100000000',dailyFeeBudget:'6',maxPayment:'90',intervalSeconds:5,ttlBlocks:10},development:{allocation:'1000000000',manager:founder.publicKey,controls:unrestrictedDevelopmentControls(),recovery:{keys:backups.map(k=>k.publicKey).sort(),threshold:2,delaySeconds:86400}}};
 const b={domain:RESERVES+'/PREPARE_NETWORK_RESERVES_V1',network:config.chainId,configHash:hash(config),generation:0,notBefore:s.height,expires:s.height+20,policy},consent=reserveConsent(hash(config),policy);await submit(wire({type:'PREPARE_NETWORK_RESERVES_V1',certificate:{body:b,approvals:approvals(b)},founderConsent:sign(consent,founder.privateKey),recoveryConsents:backups.map(k=>({key:k.publicKey,signature:sign(consent,k.privateKey)}))}));await until(async()=>{s=await state();return s.networkReserves;});
 const lp={version:1,activation:s.height+12,challengeBlocks:4,suspensionBlocks:8,exceptionDelaySeconds:86400,penaltyBps:2000,maxOpen:32,founderKey:founder.publicKey,founderGroup:hash('synthetic-founder'),founderNodes:[]},lb={domain:LIABILITY+'/POLICY',network:config.chainId,configHash:hash(config),generation:0,notBefore:s.height,expires:s.height+8,policy:lp};await submit(wire({type:'PREPARE_PAYMENT_LIABILITY_V1',certificate:{body:lb,approvals:approvals(lb)},founderConsent:sign(lb,founder.privateKey)}));await until(async()=>{s=await state();return s.money.liability;});
 for(let i=0;i<6;i++){const node=f.ids[i];await submit(wire({type:'ACCEPT_PAYMENT_LIABILITY_V1',node,signature:sign(liabilityConsent(s.money,node),f.nodeKeys[node])},f.workers[i]));}await until(async()=>{s=await state();return s.height>=lp.activation&&Object.keys(s.money.liability.consents).length===6;});pass('real BFT: zero-funded protection activated with worker opt-in; no issuance');
 const input=Object.entries(s.money.outputs).find(([,o])=>o.owner===f.alice.publicKey&&BigInt(o.value)>100n);assert(input);const beforeSupply=s.money.supply,priorStake=s.money.nodes[f.ids[0]].stake;
 const i=f.intent({inputs:[input[0]],lastReserve:s.money.height+20,deadline:s.money.height+50});i.pid=resourcePaymentId(i,hash(config));await submit(wire({type:'RESERVE',signed:f.sign(i)}));await until(async()=>{s=await state();return s.money.requests[i.pid]?.status==='RESERVED';});
 const body=attestationBody(s.money,i.pid,0,f.ids[0],{recipient:f.bob.publicKey,value:'999',partValue:'50'}),attestation={body,signature:sign(body,f.nodeKeys[f.ids[0]])};assert.notEqual((await send(wire({type:'REPORT_PAYMENT_FAULT_V1',attestation:{...attestation,signature:sign(body,keys().privateKey)}}))).code,0);
 await submit(wire({type:'REPORT_PAYMENT_FAULT_V1',attestation}));await until(async()=>{s=await state();return s.money.liability.discipline[f.ids[0]]?.suspended;});pass('real BFT: forged accusation rejected; signed false fact quarantines only culprit');
 for(const n of [7,8,9])await stopNode(n);let h=(await state()).height;await until(async()=>(await state()).height>h+2);await stopNode(6);await new Promise(r=>setTimeout(r,3000));h=(await state()).height;await new Promise(r=>setTimeout(r,3000));assert.equal((await state()).height,h);await startNode(6);await until(async()=>(await state()).height>h);for(const n of [7,8,9])await startNode(n);pass('real BFT: 7/10 progresses, 6/10 pauses without local compensation');
 await until(async()=>{s=await state();return s.money.requests[i.pid]?.status==='EXPIRED'&&!s.money.liability.records[i.pid];},90000);assert.equal(s.money.outputs[oid(i.pid,'refund')].value,String(BigInt(input[1].value)-1n));assert.equal(s.money.liability.pool,'9');assert.equal(s.money.liability.protection.compensated,'1');assert.equal(s.money.nodes[f.ids[0]].stake,String(BigInt(priorStake)-10n));assert.equal(s.money.supply,beforeSupply);assert(!s.networkReserves.issued&&!s.rewards);pass('real BFT: automatic fee compensation, collateral penalty and reserve accounting agree');
 const q={type:'QUEUE_PROTECTION_PAYMENT_V1',managementEpoch:0,sequence:1,recipient:f.bob.publicKey,value:'2',purpose:'Synthetic exceptional recovery',reference:hash('incident'),validUntil:s.money.time+300};assert.notEqual((await send(wire(q))).code,0);await submit(wire(q,founder));await until(async()=>{s=await state();return s.money.liability.protection.pending;});assert.notEqual((await send(wire({type:'EXECUTE_PROTECTION_PAYMENT_V1',sequence:1}))).code,0);await submit(wire({type:'CANCEL_PROTECTION_PAYMENT_V1',managementEpoch:0,sequence:1},founder));await until(async()=>{s=await state();return !s.money.liability.protection.pending;});pass('real BFT: founder-only queue, enforced delay and cancellation');
 await stopNode(0);await startNode(0);await until(async()=>{s=await state();return s.money.liability.pool==='9';});const at=s.height;await until(async()=>(await Promise.all(Array.from({length:10},(_,n)=>state(n)))).every(q=>q.height>=at));const snapshots=await Promise.all(Array.from({length:10},(_,n)=>local(n,{method:'snapshot',key:String(at)})));assert.equal(new Set(snapshots.map(q=>stateHash(q.value.state,config))).size,1);pass('real BFT: restart and all ten application hashes preserve exactly-once settlement');
}
